using System.Buffers.Binary;
using System.Security.Cryptography;
using ProsperoPkgTool.Content;

namespace ProsperoPkgTool.Tests;

/// <summary>
/// Validates the clean-room fake-SELF builder against byte-exact vectors produced by the
/// reference scene engine (LibProsperoPkg 1.2.0). The vectors are synthetic 64-bit ELF
/// modules, so the test carries no dependency on a real copyrighted module.
/// </summary>
public sealed class ProsperoSelfBuilderTests
{
    // Synthetic ELF with three content segments (PT_LOAD, PT_LOAD, PT_MODULE_DATA) and an
    // embedded .sceversion section; the paired fake-SELF is the reference engine output.
    private const string ElfWithSceVersionBase64 =
        "";

    private const string ExpectedFselfWithSceVersionBase64 =
        "";

    // Same ELF with the section table truncated to drop .sceversion; the reference engine
    // synthesizes a record from the application .sceversion tuple (name "testmod").
    private const string ElfWithoutSceVersionBase64 =
        "";

    private const string ExpectedFselfSynthesizedBase64 =
        "";

    private static byte[] Decode(string base64) => Convert.FromBase64String(base64);

    [Fact]
    public void MakeFself_MatchesReference_ForElfWithSceVersionSection()
    {
        byte[] elf = Decode(ElfWithSceVersionBase64);
        byte[] expected = Decode(ExpectedFselfWithSceVersionBase64);

        byte[] actual = ProsperoSelfBuilder.MakeFself(elf);

        Assert.Equal(expected, actual);
    }

    [Fact]
    public void MakeFself_MatchesReference_ForStrippedModuleWithSynthesizedSceVersion()
    {
        byte[] elf = Decode(ElfWithoutSceVersionBase64);
        byte[] expected = Decode(ExpectedFselfSynthesizedBase64);
        byte[] applicationRecord = { 0x02, 0x00, 0x00, 0x09, 0x00, 0x00, 0x00, 0x01 };

        byte[] actual = ProsperoSelfBuilder.MakeFself(elf, new FselfOptions
        {
            SceVersionName = "testmod",
            SceVersionRecord = applicationRecord,
        });

        Assert.Equal(expected, actual);
    }

    [Fact]
    public void MakeFself_ContainerHeader_IsWellFormed()
    {
        byte[] elf = Decode(ElfWithSceVersionBase64);

        byte[] fself = ProsperoSelfBuilder.MakeFself(elf);

        Assert.Equal(ProsperoSelfBuilder.Magic, BinaryPrimitives.ReadUInt32LittleEndian(fself));
        Assert.Equal(0x10, fself[0x04]);
        Assert.Equal(0x01, fself[0x05]);
        Assert.Equal(0x01, fself[0x06]);
        Assert.Equal(0x12, fself[0x07]);
        Assert.Equal(0x10000101u, BinaryPrimitives.ReadUInt32LittleEndian(fself.AsSpan(0x08)));
        int headerSize = BinaryPrimitives.ReadUInt16LittleEndian(fself.AsSpan(0x0C));
        int metaSize = BinaryPrimitives.ReadUInt16LittleEndian(fself.AsSpan(0x0E));
        Assert.Equal(6, BinaryPrimitives.ReadUInt16LittleEndian(fself.AsSpan(0x18)));
        Assert.Equal(0x0032, BinaryPrimitives.ReadUInt16LittleEndian(fself.AsSpan(0x1A)));
        Assert.Equal((ulong)(headerSize + metaSize), BinaryPrimitives.ReadUInt64LittleEndian(fself.AsSpan(0x20 + 0x08)));
        Assert.Equal(0x00010000u, BinaryPrimitives.ReadUInt32LittleEndian(fself.AsSpan(headerSize + 6 * 0x50 + 0x30)));
    }

    [Fact]
    public void MakeFself_ExtInfoDigest_IsSha256OfElf()
    {
        byte[] elf = Decode(ElfWithSceVersionBase64);

        byte[] fself = ProsperoSelfBuilder.MakeFself(elf);

        int extInfoOffset = BinaryPrimitives.ReadUInt16LittleEndian(fself.AsSpan(0x0C)) - 0x40 - 0x30;
        byte[] expectedDigest = SHA256.HashData(elf);
        Assert.Equal(expectedDigest, fself.AsSpan(extInfoOffset + 0x20, 0x20).ToArray());
        Assert.Equal(3ul, BinaryPrimitives.ReadUInt64LittleEndian(fself.AsSpan(extInfoOffset + 0x40)));
    }

    [Fact]
    public void MakeFself_CopiesSegmentPayloads()
    {
        byte[] elf = Decode(ElfWithSceVersionBase64);

        byte[] fself = ProsperoSelfBuilder.MakeFself(elf);

        // Segment data entries hold the raw segment payloads (0xAA, 0xBB, 0xCC runs). Each data
        // segment is preceded by its own zero-filled digest block, so the payloads are not adjacent.
        static int DataOffset(byte[] fself, int pairIndex) =>
            (int)BinaryPrimitives.ReadUInt64LittleEndian(fself.AsSpan(0x20 + (pairIndex * 2 + 1) * 0x20 + 0x08));
        int first = DataOffset(fself, 0);
        int second = DataOffset(fself, 1);
        int third = DataOffset(fself, 2);
        Assert.Equal(0xAA, fself[first]);
        Assert.Equal(0xBB, fself[second]);
        Assert.Equal(0xCC, fself[third]);
    }

    [Fact]
    public void TryGetSceVersionRecord_ReadsEmbeddedSection()
    {
        byte[] elf = Decode(ElfWithSceVersionBase64);

        bool found = ProsperoSelfBuilder.TryGetSceVersionRecord(elf, out byte[] record);

        Assert.True(found);
        Assert.Equal(new byte[] { 0x02, 0x00, 0x00, 0x09, 0x00, 0x00, 0x00, 0x01 }, record);
    }

    [Fact]
    public void TryGetSceVersionRecord_ReturnsFalse_WhenAbsent()
    {
        byte[] elf = Decode(ElfWithoutSceVersionBase64);

        Assert.False(ProsperoSelfBuilder.TryGetSceVersionRecord(elf, out _));
    }

    [Fact]
    public void IsElf_And_IsSelf_ClassifyBuffers()
    {
        byte[] elf = Decode(ElfWithSceVersionBase64);
        byte[] fself = ProsperoSelfBuilder.MakeFself(elf);

        Assert.True(ProsperoSelfBuilder.IsElf(elf));
        Assert.False(ProsperoSelfBuilder.IsSelf(elf));
        Assert.True(ProsperoSelfBuilder.IsSelf(fself));
        Assert.False(ProsperoSelfBuilder.IsElf(fself));
        Assert.False(ProsperoSelfBuilder.IsElf(new byte[4]));
    }

    [Fact]
    public void MakeFself_RejectsNonElf()
    {
        Assert.Throws<ArgumentException>(() => ProsperoSelfBuilder.MakeFself(new byte[0x40]));
    }

    [Fact]
    public void MakeFself_Rejects32BitElf()
    {
        byte[] elf = Decode(ElfWithSceVersionBase64);
        elf[4] = 1;

        Assert.Throws<ArgumentException>(() => ProsperoSelfBuilder.MakeFself(elf));
    }
}
